package com.ridego.backend.controller;
import com.ridego.backend.service.AuthService;import jakarta.servlet.http.HttpServletRequest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.util.*;import java.math.BigDecimal;
@RestController @RequestMapping("/api/admin") public class OperationsController {
 private final JdbcTemplate db;private final AuthService auth;public OperationsController(JdbcTemplate db,AuthService auth){this.db=db;this.auth=auth;}
 private Map<String,Object> admin(HttpServletRequest r){String h=r.getHeader("Authorization");return auth.requireRole(h!=null&&h.startsWith("Bearer ")?h.substring(7):null,"ADMIN");}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(HttpServletRequest r){admin(r);return Map.of("customers",count("select count(*) from users where role='CUSTOMER'"),"cars",count("select count(*) from cars where is_active=1"),"availableCars",count("select count(*) from cars where is_active=1 and status='AVAILABLE'"),"reservations",count("select count(*) from reservations"),"activeRentals",count("select count(*) from rentals where status='ACTIVE'"),"openMessages",count("select count(*) from contact_messages where status<>'RESOLVED'"));}
 @GetMapping("/reservations") public List<Map<String,Object>> reservations(HttpServletRequest r){admin(r);return db.queryForList("select r.reservation_id as id,r.booking_reference as bookingReference,r.status,r.start_date as startDate,r.end_date as endDate,r.total_price as totalPrice,u.first_name||' '||u.last_name as customer,c.brand||' '||c.model as car from reservations r join users u on u.user_id=r.customer_id join cars c on c.car_id=r.car_id order by r.created_at desc");}
 @GetMapping("/users") public List<Map<String,Object>> users(HttpServletRequest r){admin(r);return db.queryForList("select user_id as id,first_name as firstName,last_name as lastName,email,phone,role,is_active as active,created_at as createdAt from users order by created_at desc");}
 @PatchMapping("/users/{id}/role") public Map<String,Object> role(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest r){admin(r);String role=Objects.toString(b.get("role"),"").toUpperCase();if(!List.of("ADMIN","CUSTOMER","INSPECTOR","MECHANIC").contains(role))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid role");db.update("update users set role=?,updated_at=systimestamp where user_id=?",role,id);return Map.of("message","User role updated");}
 @PostMapping("/cars") public Map<String,Object> addCar(@RequestBody Map<String,Object>b,HttpServletRequest r){admin(r);db.update("insert into cars(category_id,location_id,registration_number,slug,brand,model,production_year,color,description,image_url,seats,transmission,fuel_type,mileage,fuel_level,daily_rate,deposit_amount,status,is_active) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'AVAILABLE',1)",n(b,"categoryId"),n(b,"locationId"),s(b,"registrationNumber"),s(b,"slug"),s(b,"brand"),s(b,"model"),n(b,"productionYear"),b.get("color"),b.get("description"),b.get("imageUrl"),n(b,"seats"),s(b,"transmission").toUpperCase(),s(b,"fuelType").toUpperCase(),b.getOrDefault("mileage",0),b.getOrDefault("fuelLevel",100),b.get("dailyRate"),b.getOrDefault("depositAmount",200));return Map.of("message","Car created","slug",b.get("slug"));}
 @PutMapping("/cars/{id}") public Map<String,Object> updateCar(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest r){admin(r);int x=db.update("update cars set category_id=?,location_id=?,brand=?,model=?,production_year=?,color=?,description=?,image_url=?,seats=?,transmission=?,fuel_type=?,daily_rate=?,deposit_amount=?,updated_at=systimestamp where car_id=?",n(b,"categoryId"),n(b,"locationId"),s(b,"brand"),s(b,"model"),n(b,"productionYear"),b.get("color"),b.get("description"),b.get("imageUrl"),n(b,"seats"),s(b,"transmission").toUpperCase(),s(b,"fuelType").toUpperCase(),b.get("dailyRate"),b.get("depositAmount"),id);if(x==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Car not found");return Map.of("message","Car updated");}
 @DeleteMapping("/cars/{id}") public Map<String,Object> deactivateCar(@PathVariable long id,HttpServletRequest r){admin(r);db.update("update cars set is_active=0,updated_at=systimestamp where car_id=?",id);return Map.of("message","Car deactivated");}
 @PostMapping("/rentals/{reservationId}/checkout") @Transactional public Map<String,Object> checkout(@PathVariable long reservationId,@RequestBody Map<String,Object>b,HttpServletRequest r){var u=admin(r);long staff=((Number)u.get("USER_ID")).longValue();var x=db.queryForList("select r.car_id,r.status,c.mileage,c.fuel_level from reservations r join cars c on c.car_id=r.car_id where r.reservation_id=? for update",reservationId);if(x.isEmpty()||!"CONFIRMED".equals(x.get(0).get("STATUS").toString()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Reservation is not ready for checkout");var row=x.get(0);db.update("insert into rentals(reservation_id,checked_out_by,checkout_mileage,checkout_fuel_level,status,notes) values(?,?,?,?, 'ACTIVE',?)",reservationId,staff,b.getOrDefault("mileage",row.get("MILEAGE")),b.getOrDefault("fuelLevel",row.get("FUEL_LEVEL")),b.get("notes"));db.update("update reservations set status='IN_PROGRESS',updated_at=systimestamp where reservation_id=?",reservationId);db.update("update cars set status='RENTED',updated_at=systimestamp where car_id=?",row.get("CAR_ID"));return Map.of("message","Rental checked out");}
 @PostMapping("/rentals/{rentalId}/return") @Transactional public Map<String,Object> checkin(@PathVariable long rentalId,@RequestBody Map<String,Object>b,HttpServletRequest r){var u=admin(r);long staff=((Number)u.get("USER_ID")).longValue();var x=db.queryForList("select r.reservation_id,rs.car_id from rentals r join reservations rs on rs.reservation_id=r.reservation_id where r.rental_id=? and r.status='ACTIVE' for update",rentalId);if(x.isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"Active rental not found");long reservation=((Number)x.get(0).get("RESERVATION_ID")).longValue(),car=((Number)x.get(0).get("CAR_ID")).longValue();long mileage=n(b,"mileage");BigDecimal fuel=new BigDecimal(s(b,"fuelLevel"));db.update("update rentals set checked_in_by=?,returned_at=systimestamp,return_mileage=?,return_fuel_level=?,status='COMPLETED',notes=coalesce(?,notes) where rental_id=?",staff,mileage,fuel,b.get("notes"),rentalId);db.update("update reservations set status='COMPLETED',updated_at=systimestamp where reservation_id=?",reservation);db.update("update cars set status='AVAILABLE',mileage=?,fuel_level=?,updated_at=systimestamp where car_id=?",mileage,fuel,car);db.update("insert into mileage_records(car_id,recorded_by,rental_id,mileage,source,notes) values(?,?,?,?,'RETURN',?)",car,staff,rentalId,mileage,b.get("notes"));return Map.of("message","Vehicle return recorded");}
 @PostMapping("/maintenance") public Map<String,Object> maintenance(@RequestBody Map<String,Object>b,HttpServletRequest r){var u=admin(r);long staff=((Number)u.get("USER_ID")).longValue();db.update("insert into maintenance(car_id,mechanic_id,created_by,maintenance_type,description,scheduled_start,scheduled_end,cost,status) values(?,?,?,?,?,to_date(?,'YYYY-MM-DD'),to_date(?,'YYYY-MM-DD'),?,'SCHEDULED')",n(b,"carId"),b.get("mechanicId"),staff,s(b,"maintenanceType"),b.get("description"),s(b,"scheduledStart"),s(b,"scheduledEnd"),b.getOrDefault("cost",0));return Map.of("message","Maintenance scheduled");}
 @PostMapping("/payments/record") public Map<String,Object> payment(@RequestBody Map<String,Object>b,HttpServletRequest r){var u=admin(r);long staff=((Number)u.get("USER_ID")).longValue();String purpose=s(b,"paymentPurpose").toUpperCase(),method=s(b,"paymentMethod").toUpperCase();String key=UUID.randomUUID().toString().replace("-","");db.update("insert into payments(reservation_id,recorded_by,request_key,payment_purpose,payment_method,amount,currency,status,provider_name,transaction_reference,paid_at) values(?,?,?,?,?,?, 'EUR','PAID',?,?,systimestamp)",n(b,"reservationId"),staff,key,purpose,method,b.get("amount"),"MANUAL",b.get("transactionReference"));return Map.of("message","Payment record created","requestKey",key);}


 @GetMapping("/rentals") public List<Map<String,Object>> rentals(HttpServletRequest r){admin(r);return db.queryForList("select rr.rental_id as id,rr.status,rr.checkout_at as checkoutAt,rr.returned_at as returnedAt,rs.booking_reference as bookingReference,c.brand||' '||c.model as car,u.first_name||' '||u.last_name as customer from rentals rr join reservations rs on rs.reservation_id=rr.reservation_id join cars c on c.car_id=rs.car_id join users u on u.user_id=rs.customer_id order by rr.checkout_at desc");}
 @PostMapping("/categories") public Map<String,Object> addCategory(@RequestBody Map<String,Object>b,HttpServletRequest r){admin(r);db.update("insert into car_categories(category_name,description,default_daily_rate,is_active) values(?,?,?,1)",s(b,"name"),b.get("description"),b.get("defaultDailyRate"));return Map.of("message","Category created");}
 @PostMapping("/locations") public Map<String,Object> addLocation(@RequestBody Map<String,Object>b,HttpServletRequest r){admin(r);db.update("insert into locations(location_name,address,city,country_code,phone,opening_hours,is_active) values(?,?,?,?,?,?,1)",s(b,"name"),s(b,"address"),s(b,"city"),b.getOrDefault("countryCode","HU"),b.get("phone"),b.get("openingHours"));return Map.of("message","Location created");}
 @PostMapping("/insurance") public Map<String,Object> addInsurance(@RequestBody Map<String,Object>b,HttpServletRequest r){admin(r);db.update("insert into insurance(insurance_name,description,daily_rate,is_active) values(?,?,?,1)",s(b,"name"),b.get("description"),b.get("dailyRate"));return Map.of("message","Insurance plan created");}
 @PatchMapping("/refunds/{id}") public Map<String,Object> refundStatus(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest r){admin(r);String status=s(b,"status").toUpperCase();if(!List.of("COMPLETED","FAILED","CANCELLED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid refund status");db.update("update refunds set status=?,completed_at=case when ?='COMPLETED' then systimestamp else null end,transaction_reference=? where refund_id=? and status='PENDING'",status,status,b.get("transactionReference"),id);return Map.of("message","Refund status updated","status",status);}
 @GetMapping("/messages") public List<Map<String,Object>> messages(HttpServletRequest r){admin(r);return db.queryForList("select message_id as id,full_name as fullName,email,subject,message_body as message,status,created_at as createdAt from contact_messages order by created_at desc");}
 @PatchMapping("/messages/{id}") public Map<String,Object> messageStatus(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest r){var u=admin(r);String status=s(b,"status").toUpperCase();if(!List.of("NEW","IN_PROGRESS","RESOLVED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid message status");db.update("update contact_messages set status=?,assigned_to=?,resolved_at=case when ?='RESOLVED' then systimestamp else null end,resolution_notes=? where message_id=?",status,u.get("USER_ID"),status,b.get("resolutionNotes"),id);return Map.of("message","Contact message updated");}
 @PostMapping("/inspections") public Map<String,Object> inspection(@RequestBody Map<String,Object>b,HttpServletRequest r){var u=auth.requireRole(bearer(r),"ADMIN","INSPECTOR");db.update("insert into inspections(rental_id,inspector_id,inspection_type,mileage,fuel_level,exterior_condition,interior_condition,notes) values(?,?,?,?,?,?,?,?)",n(b,"rentalId"),u.get("USER_ID"),s(b,"inspectionType").toUpperCase(),n(b,"mileage"),b.get("fuelLevel"),s(b,"exteriorCondition"),s(b,"interiorCondition"),b.get("notes"));return Map.of("message","Inspection saved");}
 @PostMapping("/damages") public Map<String,Object> damage(@RequestBody Map<String,Object>b,HttpServletRequest r){admin(r);db.update("insert into damages(inspection_id,damage_type,description,severity,photo_url,estimated_repair_cost,status) values(?,?,?,?,?,?,'OPEN')",n(b,"inspectionId"),s(b,"damageType"),s(b,"description"),s(b,"severity").toUpperCase(),b.get("photoUrl"),b.getOrDefault("estimatedRepairCost",0));return Map.of("message","Damage record created");}
 @PostMapping("/charges") public Map<String,Object> charge(@RequestBody Map<String,Object>b,HttpServletRequest r){var u=admin(r);db.update("insert into rental_charges(rental_id,damage_id,created_by,charge_type,description,amount,status) values(?,?,?,?,?,?,'ACTIVE')",n(b,"rentalId"),b.get("damageId"),u.get("USER_ID"),s(b,"chargeType").toUpperCase(),s(b,"description"),b.get("amount"));return Map.of("message","Additional charge created");}
 @PostMapping("/refunds") @Transactional public Map<String,Object> refund(@RequestBody Map<String,Object>b,HttpServletRequest r){var u=admin(r);long paymentId=n(b,"paymentId");db.queryForMap("select payment_id from payments where payment_id=? and status='PAID' for update",paymentId);BigDecimal amount=new BigDecimal(s(b,"amount"));BigDecimal paid=db.queryForObject("select amount from payments where payment_id=?",BigDecimal.class,paymentId);BigDecimal already=db.queryForObject("select nvl(sum(amount),0) from refunds where payment_id=? and status in ('PENDING','COMPLETED')",BigDecimal.class,paymentId);if(amount.signum()<=0||already.add(amount).compareTo(paid)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Refund amount exceeds the remaining paid amount");String key=UUID.randomUUID().toString().replace("-","");db.update("insert into refunds(payment_id,processed_by,request_key,amount,reason,status) values(?,?,?,?,?,'PENDING')",paymentId,u.get("USER_ID"),key,amount,s(b,"reason"));return Map.of("message","Refund request recorded as pending","requestKey",key);}
 @PostMapping("/mileage") public Map<String,Object> mileage(@RequestBody Map<String,Object>b,HttpServletRequest r){var u=admin(r);long car=n(b,"carId"),value=n(b,"mileage");db.update("insert into mileage_records(car_id,recorded_by,mileage,source,notes) values(?,?,?,'MANUAL',?)",car,u.get("USER_ID"),value,b.get("notes"));db.update("update cars set mileage=?,updated_at=systimestamp where car_id=? and mileage<=?",value,car,value);return Map.of("message","Mileage record saved");}
 @PatchMapping("/maintenance/{id}/status") public Map<String,Object> maintenanceStatus(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest r){admin(r);String status=s(b,"status").toUpperCase();if(!List.of("SCHEDULED","IN_PROGRESS","COMPLETED","CANCELLED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid maintenance status");var rows=db.queryForList("select car_id from maintenance where maintenance_id=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Maintenance record not found");long carId=((Number)rows.get(0).get("CAR_ID")).longValue();db.update("update maintenance set status=?,started_at=case when ?='IN_PROGRESS' then systimestamp else started_at end,completed_at=case when ?='COMPLETED' then systimestamp else completed_at end,completion_notes=? where maintenance_id=?",status,status,status,b.get("completionNotes"),id);if(status.equals("IN_PROGRESS"))db.update("update cars set status='MAINTENANCE',updated_at=systimestamp where car_id=? and status<>'RENTED'",carId);if(status.equals("COMPLETED")||status.equals("CANCELLED")){int remaining=db.queryForObject("select count(*) from maintenance where car_id=? and maintenance_id<>? and status in ('IN_PROGRESS')",Integer.class,carId,id);if(remaining==0)db.update("update cars set status='AVAILABLE',updated_at=systimestamp where car_id=? and status='MAINTENANCE'",carId);}return Map.of("message","Maintenance status updated");}
 private String bearer(HttpServletRequest r){String h=r.getHeader("Authorization");return h!=null&&h.startsWith("Bearer ")?h.substring(7):null;}
 private int count(String q){return db.queryForObject(q,Integer.class);}private long n(Map<String,Object>b,String k){return Long.parseLong(s(b,k));}private String s(Map<String,Object>b,String k){Object v=b.get(k);if(v==null||v.toString().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,k+" is required");return v.toString();}
}
